"use client";

import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, interpolate, useCurrentFrame } from "remotion";
import { resolveEasing, splitText } from "@/registry/snap-cn/text-reveal";

const { fontFamily: FONT_FAMILY } = loadFont("normal", {
  weights: ["400", "500", "600", "700"],
  subsets: ["latin"],
});

export type TestimonialVariant = "card" | "x-post";
export type TestimonialReveal = "stagger" | "none";
export type TestimonialTheme = "light" | "dark";

export interface Testimonial {
  quote: string;
  name: string;
  title?: string;
  company?: string;
  avatarUrl?: string;
  /** 0–5. Stars draw on one by one, 4 frames each. */
  rating?: number;
}

export interface TestimonialCardProps {
  quote?: string;
  name?: string;
  title?: string;
  company?: string;
  /** Empty renders a deterministic initial fallback — no network needed. */
  avatarUrl?: string;
  /** 0–5 stars. 0 (or omitted) hides the star row. */
  rating?: number;
  /** "card" is a framed quote card; "x-post" restyles it as an X post. */
  variant?: TestimonialVariant;
  /** "stagger" fade-rises the quote word by word; "none" shows it instantly. */
  reveal?: TestimonialReveal;
  /** Carousel mode: crossfades through these items, replacing the single-testimonial props. */
  stack?: Testimonial[];
  theme?: TestimonialTheme;
  /** Star color. */
  accentColor?: string;
  cardWidth?: number;
  /** Frames each stack item holds before crossfading to the next. */
  framesPerItem?: number;
  /** Crossfade length between stack items, in frames. */
  crossfadeFrames?: number;
  speed?: number;
  className?: string;
}

interface Theme {
  cardBg: string;
  cardBorder: string;
  fg: string;
  fgMuted: string;
  avatarBg: string;
}

export const THEMES: Record<TestimonialTheme, Theme> = {
  light: {
    cardBg: "#FFFFFF",
    cardBorder: "#E4E7EC",
    fg: "#101828",
    fgMuted: "#667085",
    avatarBg: "#F2F4F7",
  },
  dark: {
    cardBg: "#141417",
    cardBorder: "#26272B",
    fg: "#FAFAFA",
    fgMuted: "#A1A1AA",
    avatarBg: "#26272B",
  },
};

/** Slot-local frame the star row starts drawing. */
export const STAR_START = 8;
/** Frames each star takes to draw on — also the per-star stagger. */
export const STAR_STEP = 4;
/** Slot-local frame the quote words start rising. */
export const QUOTE_START = 14;
/** Frames between consecutive quote words. */
export const QUOTE_STAGGER = 2;
/** Frames one quote word takes to fade-rise. */
export const QUOTE_DURATION = 16;

/** Clamps a rating to an integer star count in [0, 5]. */
export function clampRating(rating: number | undefined): number {
  if (rating === undefined || !Number.isFinite(rating)) return 0;
  return Math.min(5, Math.max(0, Math.round(rating)));
}

/**
 * Draw progress (0–1) of star `index`. Star i starts at
 * `start + i * step` and completes `step` frames later, so stars
 * draw on strictly one by one.
 */
export function starProgress(
  frame: number,
  index: number,
  start: number = STAR_START,
  step: number = STAR_STEP,
): number {
  const p = (frame - start - index * step) / step;
  return Math.max(0, Math.min(1, p));
}

/** Slot-local frame the meta row (avatar / name / title) starts fading in. */
export function metaStart(
  wordCount: number,
  quoteStart: number = QUOTE_START,
  stagger: number = QUOTE_STAGGER,
): number {
  return quoteStart + wordCount * stagger + 6;
}

export interface CarouselSlot {
  index: number;
  /** Crossfade opacity of this slot, 0–1. */
  opacity: number;
  /** Frame local to this slot — inner animations restart per item. */
  localFrame: number;
}

/**
 * Which stack items are visible at `frame` and how faded they are.
 * Item i owns [i * framesPerItem, (i + 1) * framesPerItem); the incoming
 * item fades in over the outgoing item's last `fadeFrames`, producing a
 * true crossfade. The last item never fades out. Returns 1–2 slots.
 */
export function carouselSlots(
  frame: number,
  count: number,
  framesPerItem: number,
  fadeFrames: number,
): CarouselSlot[] {
  if (count <= 0) return [];
  if (count === 1) return [{ index: 0, opacity: 1, localFrame: frame }];
  const fade = Math.max(1, Math.min(fadeFrames, framesPerItem - 1));
  const slots: CarouselSlot[] = [];
  for (let i = 0; i < count; i++) {
    const start = i === 0 ? 0 : i * framesPerItem - fade;
    const end = (i + 1) * framesPerItem;
    if (frame < start) continue;
    if (i < count - 1 && frame >= end) continue;
    let opacity = 1;
    if (i > 0) {
      opacity = Math.min(1, (frame - start) / fade);
    }
    if (i < count - 1 && frame >= end - fade) {
      opacity = Math.min(opacity, Math.max(0, (end - frame) / fade));
    }
    slots.push({ index: i, opacity, localFrame: frame - start });
  }
  return slots;
}

const SMOOTH = resolveEasing("smooth");

const STAR_PATH =
  "M12 2.5l2.95 5.98 6.6.96-4.78 4.66 1.13 6.57L12 17.57l-5.9 3.1 1.13-6.57L2.45 9.44l6.6-.96L12 2.5z";

const X_LOGO_PATH =
  "M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z";

function StarRow({
  frame,
  stars,
  size,
  color,
}: {
  frame: number;
  stars: number;
  size: number;
  color: string;
}) {
  return (
    <div style={{ display: "flex", gap: Math.round(size * 0.22) }}>
      {Array.from({ length: stars }).map((_, i) => (
        <svg
          // biome-ignore lint/suspicious/noArrayIndexKey: stars are positional and never reorder
          key={i}
          width={size}
          height={size}
          viewBox="0 0 24 24"
          role="img"
          aria-label="star"
          style={{
            opacity: starProgress(frame, i),
            scale: String(0.4 + 0.6 * SMOOTH(starProgress(frame, i))),
            transformOrigin: "50% 60%",
          }}
        >
          <path d={STAR_PATH} fill={color} />
        </svg>
      ))}
    </div>
  );
}

function QuoteWords({
  frame,
  text,
  reveal,
  withQuotes,
}: {
  frame: number;
  text: string;
  reveal: TestimonialReveal;
  withQuotes: boolean;
}) {
  const words = splitText(text, "word");
  return (
    <span>
      {words.map((word, i) => {
        const display =
          (withQuotes && i === 0 ? "“" : "") +
          word +
          (withQuotes && i === words.length - 1 ? "”" : "");
        const p =
          reveal === "stagger"
            ? interpolate(
                frame - QUOTE_START - i * QUOTE_STAGGER,
                [0, QUOTE_DURATION],
                [0, 1],
                {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: SMOOTH,
                },
              )
            : 1;
        return (
          <span
            // biome-ignore lint/suspicious/noArrayIndexKey: words are positional and never reorder
            key={i}
            style={{
              display: "inline-block",
              opacity: p,
              translate: `0px ${14 * (1 - p)}px`,
              marginRight: i < words.length - 1 ? "0.28em" : undefined,
            }}
          >
            {display}
          </span>
        );
      })}
    </span>
  );
}

function Avatar({
  url,
  name,
  size,
  theme,
}: {
  url: string | undefined;
  name: string;
  size: number;
  theme: Theme;
}) {
  if (url) {
    return (
      <Img
        src={url}
        crossOrigin="anonymous"
        style={{
          width: size,
          height: size,
          borderRadius: "50%",
          objectFit: "cover",
          flexShrink: 0,
        }}
      />
    );
  }
  return (
    <div
      style={{
        width: size,
        height: size,
        borderRadius: "50%",
        background: theme.avatarBg,
        color: theme.fgMuted,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: size * 0.42,
        fontWeight: 600,
        flexShrink: 0,
      }}
    >
      {name.trim().charAt(0).toUpperCase()}
    </div>
  );
}

function SingleTestimonial({
  frame,
  item,
  variant,
  reveal,
  theme,
  accentColor,
  cardWidth,
  className,
}: {
  frame: number;
  item: Testimonial;
  variant: TestimonialVariant;
  reveal: TestimonialReveal;
  theme: Theme;
  accentColor: string;
  cardWidth: number;
  className?: string;
}) {
  const stars = clampRating(item.rating);
  const words = splitText(item.quote, "word");
  const ms = reveal === "stagger" ? metaStart(words.length) : 0;
  const metaP = interpolate(frame, [ms, ms + 12], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: SMOOTH,
  });
  const byline = [item.title, item.company].filter(Boolean).join(", ");

  if (variant === "x-post") {
    return (
      <div
        className={className}
        style={{
          width: cardWidth,
          background: theme.cardBg,
          border: `1px solid ${theme.cardBorder}`,
          borderRadius: 10,
          padding: "26px 30px",
          boxSizing: "border-box",
          fontFamily: FONT_FAMILY,
          opacity: interpolate(frame, [0, 12], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: SMOOTH,
          }),
          translate: `0px ${interpolate(frame, [0, 14], [16, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: SMOOTH,
          })}px`,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <Avatar
            url={item.avatarUrl}
            name={item.name}
            size={44}
            theme={theme}
          />
          <div style={{ minWidth: 0 }}>
            <div
              style={{
                fontSize: 15,
                fontWeight: 700,
                color: theme.fg,
                letterSpacing: "-0.01em",
                lineHeight: 1.3,
              }}
            >
              {item.name}
            </div>
            <div
              style={{ fontSize: 14, color: theme.fgMuted, lineHeight: 1.3 }}
            >
              {byline}
            </div>
          </div>
          <svg
            width={18}
            height={18}
            viewBox="0 0 24 24"
            role="img"
            aria-label="X"
            style={{ marginLeft: "auto", flexShrink: 0 }}
          >
            <path d={X_LOGO_PATH} fill={theme.fg} />
          </svg>
        </div>
        <div
          style={{
            marginTop: 16,
            fontSize: 22,
            fontWeight: 400,
            color: theme.fg,
            letterSpacing: "-0.01em",
            lineHeight: 1.4,
          }}
        >
          <QuoteWords
            frame={frame}
            text={item.quote}
            reveal={reveal}
            withQuotes={false}
          />
        </div>
        {stars > 0 && (
          <div style={{ marginTop: 14 }}>
            <StarRow
              frame={frame}
              stars={stars}
              size={17}
              color={accentColor}
            />
          </div>
        )}
        <div
          style={{
            marginTop: 14,
            fontSize: 14,
            color: theme.fgMuted,
            opacity: metaP,
            translate: `0px ${8 * (1 - metaP)}px`,
          }}
        >
          9:41 AM · Jul 2, 2026
        </div>
      </div>
    );
  }

  return (
    <div
      className={className}
      style={{
        width: cardWidth,
        background: theme.cardBg,
        border: `1px solid ${theme.cardBorder}`,
        borderRadius: 10,
        padding: "40px 44px",
        boxSizing: "border-box",
        fontFamily: FONT_FAMILY,
        opacity: interpolate(frame, [0, 12], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: SMOOTH,
        }),
        translate: `0px ${interpolate(frame, [0, 14], [16, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: SMOOTH,
        })}px`,
      }}
    >
      {stars > 0 && (
        <div style={{ marginBottom: 20 }}>
          <StarRow frame={frame} stars={stars} size={22} color={accentColor} />
        </div>
      )}
      <blockquote
        style={{
          margin: 0,
          fontSize: 26,
          fontWeight: 500,
          color: theme.fg,
          letterSpacing: "-0.01em",
          lineHeight: 1.45,
        }}
      >
        <QuoteWords
          frame={frame}
          text={item.quote}
          reveal={reveal}
          withQuotes
        />
      </blockquote>
      <div
        style={{
          marginTop: 26,
          display: "flex",
          alignItems: "center",
          gap: 14,
          opacity: metaP,
          translate: `0px ${10 * (1 - metaP)}px`,
        }}
      >
        <Avatar url={item.avatarUrl} name={item.name} size={44} theme={theme} />
        <div>
          <div
            style={{
              fontSize: 14,
              fontWeight: 600,
              color: theme.fg,
              letterSpacing: "-0.01em",
              lineHeight: 1.4,
            }}
          >
            {item.name}
          </div>
          <div style={{ fontSize: 14, color: theme.fgMuted, lineHeight: 1.4 }}>
            {byline}
          </div>
        </div>
      </div>
    </div>
  );
}

export function TestimonialCard({
  quote = "Acme cut our close time from 5 days to 4 hours.",
  name = "Priya N.",
  title = "CFO",
  company = "Initech",
  avatarUrl = "",
  rating = 5,
  variant = "card",
  reveal = "stagger",
  stack,
  theme = "light",
  accentColor = "#F79009",
  cardWidth = 620,
  framesPerItem = 90,
  crossfadeFrames = 12,
  speed = 1,
  className,
}: TestimonialCardProps) {
  const frame = useCurrentFrame() * speed;
  const items: Testimonial[] =
    stack && stack.length > 0
      ? stack
      : [{ quote, name, title, company, avatarUrl, rating }];
  const slots = carouselSlots(
    frame,
    items.length,
    framesPerItem,
    crossfadeFrames,
  );
  const t = THEMES[theme];

  return (
    <AbsoluteFill
      style={{
        justifyContent: "center",
        alignItems: "center",
        background: "transparent",
      }}
    >
      {slots.map((slot) => (
        <AbsoluteFill
          key={slot.index}
          style={{
            justifyContent: "center",
            alignItems: "center",
            opacity: slot.opacity,
          }}
        >
          <SingleTestimonial
            frame={slot.localFrame}
            item={items[slot.index]}
            variant={variant}
            reveal={reveal}
            theme={t}
            accentColor={accentColor}
            cardWidth={cardWidth}
            className={className}
          />
        </AbsoluteFill>
      ))}
    </AbsoluteFill>
  );
}
